import {
  NumberInput as NumberInputPrimitive,
  useNumberInput,
  useNumberInputContext,
} from '@ark-ui/solid/number-input';
import { clsx } from 'clsx';
import { children, splitProps } from 'solid-js';
import type { ComponentProps } from 'solid-js';
import { MinusIcon, PlusIcon } from '@/lib/moduix/icons/ui';
import styles from './NumberInput.module.css';

type NumberInputSize = 'xs' | 'sm' | 'md' | 'lg' | 'xl';
type NumberInputRootProps = ComponentProps<typeof NumberInputPrimitive.Root> & {
  size?: NumberInputSize;
};
type NumberInputRootProviderProps = ComponentProps<typeof NumberInputPrimitive.RootProvider> & {
  size?: NumberInputSize;
};

function NumberInput(props: NumberInputRootProps) {
  const [local, others] = splitProps(props, ['children', 'class', 'size']);

  return (
    <NumberInputPrimitive.Root
      class={clsx(styles.root, local.class)}
      {...others}
      data-size={local.size ?? 'md'}
      data-slot="number-input-root"
    >
      {local.children}
    </NumberInputPrimitive.Root>
  );
}

function NumberInputRootProvider(props: NumberInputRootProviderProps) {
  const [local, others] = splitProps(props, ['children', 'class', 'size']);

  return (
    <NumberInputPrimitive.RootProvider
      class={clsx(styles.root, local.class)}
      {...others}
      data-size={local.size ?? 'md'}
      data-slot="number-input-root-provider"
    >
      {local.children}
    </NumberInputPrimitive.RootProvider>
  );
}

function NumberInputLabel(props: ComponentProps<typeof NumberInputPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <NumberInputPrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="number-input-label"
    />
  );
}

function NumberInputScrubber(props: ComponentProps<typeof NumberInputPrimitive.Scrubber>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <NumberInputPrimitive.Scrubber
      class={clsx(styles.scrubber, local.class)}
      {...others}
      data-slot="number-input-scrubber"
    />
  );
}

function NumberInputControl(props: ComponentProps<typeof NumberInputPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <NumberInputPrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="number-input-control"
    />
  );
}

function NumberInputDecrementTrigger(
  props: ComponentProps<typeof NumberInputPrimitive.DecrementTrigger>,
) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <NumberInputPrimitive.DecrementTrigger
      class={clsx(styles.decrementTrigger, local.class)}
      {...others}
      data-slot="number-input-decrement-trigger"
    >
      {resolvedChildren() ?? <MinusIcon />}
    </NumberInputPrimitive.DecrementTrigger>
  );
}

function NumberInputInput(props: ComponentProps<typeof NumberInputPrimitive.Input>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <NumberInputPrimitive.Input
      class={clsx(styles.input, local.class)}
      {...others}
      data-slot="number-input-input"
    />
  );
}

function NumberInputIncrementTrigger(
  props: ComponentProps<typeof NumberInputPrimitive.IncrementTrigger>,
) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <NumberInputPrimitive.IncrementTrigger
      class={clsx(styles.incrementTrigger, local.class)}
      {...others}
      data-slot="number-input-increment-trigger"
    >
      {resolvedChildren() ?? <PlusIcon />}
    </NumberInputPrimitive.IncrementTrigger>
  );
}

function NumberInputValueText(props: ComponentProps<typeof NumberInputPrimitive.ValueText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <NumberInputPrimitive.ValueText
      class={clsx(styles.valueText, local.class)}
      {...others}
      data-slot="number-input-value-text"
    />
  );
}

type NumberInputFieldProps = Omit<
  ComponentProps<typeof NumberInputControl>,
  'asChild' | 'children'
>;

function NumberInputField(props: NumberInputFieldProps) {
  return (
    <NumberInputControl {...props}>
      <NumberInputDecrementTrigger />
      <NumberInputInput />
      <NumberInputIncrementTrigger />
    </NumberInputControl>
  );
}

const NumberInputContext = NumberInputPrimitive.Context;

export {
  NumberInput,
  NumberInputContext,
  NumberInputControl,
  NumberInputDecrementTrigger,
  NumberInputField,
  NumberInputIncrementTrigger,
  NumberInputInput,
  NumberInputLabel,
  NumberInputRootProvider,
  NumberInputScrubber,
  NumberInputValueText,
  useNumberInput,
  useNumberInputContext,
};
export type {
  NumberInputContextProps,
  NumberInputControlProps,
  NumberInputDecrementTriggerProps,
  NumberInputFocusChangeDetails,
  NumberInputIncrementTriggerProps,
  NumberInputInputProps,
  NumberInputLabelProps,
  NumberInputScrubberProps,
  NumberInputValueChangeDetails,
  NumberInputValueInvalidDetails,
  NumberInputValueTextProps,
  UseNumberInputContext,
  UseNumberInputProps,
  UseNumberInputReturn,
} from '@ark-ui/solid/number-input';

export type { NumberInputRootProps, NumberInputRootProviderProps, NumberInputSize };

@layer moduix.components {
  .root {
    --_number-input-height: var(--moduix-size-md);
    --_number-input-padding-x: var(--moduix-spacing-3);
    --_number-input-padding-y: var(--moduix-spacing-1);
    --_number-input-font-size: var(--moduix-text-md);
    --_number-input-line-height: var(--moduix-line-height-text-md);
    --_number-input-icon-size: var(--moduix-spacing-3-5);

    display: flex;
    flex-direction: column;
    align-items: flex-start;
    gap: var(--moduix-spacing-1);

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);

      :where(
          [data-slot='field-root'][data-disabled],
          [data-slot='field-root-provider'][data-disabled],
          [data-slot='fieldset-root'][data-disabled],
          [data-slot='fieldset-root-provider'][data-disabled]
        )
        & {
        opacity: 1;
      }
    }
    &[data-size='xs'] {
      --_number-input-height: var(--moduix-size-xs);
      --_number-input-padding-x: var(--moduix-spacing-2);
      --_number-input-padding-y: var(--moduix-spacing-0-5);
      --_number-input-font-size: var(--moduix-text-xs);
      --_number-input-line-height: var(--moduix-line-height-text-xs);
      --_number-input-icon-size: var(--moduix-spacing-3);
    }

    &[data-size='sm'] {
      --_number-input-height: var(--moduix-size-sm);
      --_number-input-padding-x: var(--moduix-spacing-2);
      --_number-input-font-size: var(--moduix-text-sm);
      --_number-input-line-height: var(--moduix-line-height-text-sm);
      --_number-input-icon-size: var(--moduix-spacing-3);
    }

    &[data-size='lg'] {
      --_number-input-height: var(--moduix-size-lg);
      --_number-input-padding-x: var(--moduix-spacing-4);
      --_number-input-font-size: var(--moduix-text-lg);
      --_number-input-line-height: var(--moduix-line-height-text-lg);
      --_number-input-icon-size: var(--moduix-spacing-4);
    }

    &[data-size='xl'] {
      --_number-input-height: var(--moduix-size-xl);
      --_number-input-padding-x: var(--moduix-spacing-4);
      --_number-input-padding-y: var(--moduix-spacing-2);
      --_number-input-font-size: var(--moduix-text-lg);
      --_number-input-line-height: var(--moduix-line-height-text-lg);
      --_number-input-icon-size: var(--moduix-spacing-4);
    }
  }

  .label {
    color: var(--moduix-color-foreground);
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
  }

  .scrubber {
    display: inline-flex;
    align-items: center;
    gap: var(--moduix-spacing-2);
    color: var(--moduix-color-foreground);
    user-select: none;
    cursor: ew-resize;

    &[data-disabled] {
      cursor: default;
    }
  }

  .control {
    display: inline-flex;
  }

  .decrementTrigger,
  .input,
  .incrementTrigger {
    box-sizing: border-box;
    height: var(--moduix-number-input-control-height, var(--_number-input-height));
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    background-color: var(--moduix-color-background);
    color: var(--moduix-color-foreground);
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);

    &:focus-visible {
      z-index: 1;
      outline-color: var(--moduix-color-ring);
    }

    .root[data-invalid] & {
      border-color: var(--moduix-color-destructive);

      &:focus-visible {
        outline-color: var(--moduix-color-destructive);
      }
    }
  }

  .decrementTrigger,
  .incrementTrigger {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
    width: var(--moduix-number-input-control-height, var(--_number-input-height));
    padding: 0;
    user-select: none;
    cursor: pointer;
    transition:
      background-color var(--moduix-transition-default),
      border-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    @media (hover: hover) {
      &:hover {
        background-color: var(--moduix-color-accent);
      }
    }

    &:active {
      background-color: var(--moduix-color-accent);
    }

    /* Ark disables a trigger at the min or max value and in read-only mode. */
    &[data-disabled] {
      color: var(--moduix-color-muted-foreground);
      pointer-events: none;
    }

    & > svg {
      width: var(--_number-input-icon-size);
      height: var(--_number-input-icon-size);
    }
  }

  .decrementTrigger {
    border-inline-end: 0;
    border-start-start-radius: var(--moduix-number-input-radius, var(--moduix-radius-md));
    border-end-start-radius: var(--moduix-number-input-radius, var(--moduix-radius-md));
  }

  .incrementTrigger {
    border-inline-start: 0;
    border-start-end-radius: var(--moduix-number-input-radius, var(--moduix-radius-md));
    border-end-end-radius: var(--moduix-number-input-radius, var(--moduix-radius-md));
  }

  .input {
    width: var(--moduix-number-input-input-width, 6rem);
    border-inline: 0;
    border-radius: 0;
    padding: var(--_number-input-padding-y) var(--_number-input-padding-x);
    font: inherit;
    font-size: var(--_number-input-font-size);
    line-height: var(--_number-input-line-height);
    font-variant-numeric: tabular-nums;
    text-align: center;
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);
  }

  .valueText {
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-sm);
    line-height: var(--moduix-line-height-text-sm);
    font-variant-numeric: tabular-nums;
  }
}
